scripts_as_text.audit_archive_alignment.py:
"""Reconstruct the previous exact-pair S47 audit and its one-row sensitivity."""
from collections import Counter, defaultdict
import csv
import itertools
import json
import math
from pathlib import Path
import random
import re
import statistics


ROOT = Path(__file__).resolve().parent
LINE_RE = re.compile(r"^<(f\d+[rv]\d*)\.(\d+),[^>]*P\d*>\s*(\S+)")
PAGE_RE = re.compile(r"^<(f\d+[rv]\d*)>\s*<!.*?\$Q=([A-Z])")
CLEAN = re.compile(r"[a-z]+(?:[.,][a-z]+)*$")
SEGMENT = re.compile(r"cth|ckh|cph|cfh|iiin|iin|iir|ch|sh|in|ir|ee|[a-z]")
PRIOR = ROOT / "predecessor" / "gap-audit-spec.json"


def read_zl(path):
    metadata, transcribed = {}, {}
    for line in path.read_text(encoding="utf-8-sig").splitlines():
        match = PAGE_RE.match(line)
        if match:
            metadata[match[1]] = match[2]
        m = LINE_RE.match(line)
        if m:
            raw = m[3].removeprefix("<%>").removesuffix("<$>")
            if CLEAN.fullmatch(raw):
                transcribed[(m[1], int(m[2]))] = raw
    return metadata, transcribed


def expected_positions(text):
    words = re.split(r"[.,]", text)
    separators = re.findall(r"[.,]", text)
    glyph_words = [SEGMENT.findall(word) for word in words]
    result = []
    for index, glyphs in enumerate(glyph_words):
        result.extend(("N", (a, b)) for a, b in itertools.pairwise(glyphs))
        if index < len(separators):
            kind = "D" if separators[index] == "." else "C"
            result.append((kind, (glyphs[-1], glyph_words[index + 1][0])))
    return result


def reconstruct(path, metadata, transcribed):
    with path.open(newline="", encoding="utf-8-sig") as stream:
        by_line = defaultdict(list)
        for row in csv.DictReader(stream, delimiter="\t"):
            by_line[(row["page"], int(row["line"]))].append(row)
    excluded = Counter()
    results = []
    for (page, line_n), observations in by_line.items():
        line = (page, line_n)
        if line not in transcribed or page not in metadata:
            excluded["unmapped_or_editorial_line"] += 1
            continue
        expected = expected_positions(transcribed[line])
        if [kind for kind, _ in expected] != [row["cls"] for row in observations]:
            excluded["glyph_or_separator_alignment_mismatch"] += 1
            continue
        try:
            widths = [float(row["w_px"]) for row in observations]
        except ValueError:
            excluded["unmeasured_width"] += 1
            continue
        options = []
        for i, (kind, pair) in enumerate(expected):
            if kind != "D":
                continue
            for j, (kind2, pair2) in enumerate(expected):
                if kind2 == "C" and pair == pair2:
                    options.append((abs(i - j), i, j, pair))
        if not options:
            excluded["lacks_mixed_label_pair"] += 1
            continue
        distance, period, comma, pair = min(options)
        threshold = float(observations[period]["thr"])
        assert threshold == float(observations[comma]["thr"])
        equal = observations[period]["counts_equal"] == "1"
        results.append({
            "locus": f"{page}.{line_n}", "folio": page, "quire": metadata[page],
            "pair": list(pair), "glyph_distance": distance, "certain_left": period < comma,
            "certain_px": widths[period], "uncertain_px": widths[comma], "threshold": threshold,
            "difference": (widths[period] - widths[comma]) / threshold,
            "counts_equal": equal,
        })
    return results, dict(excluded), len(by_line)


def summary(rows):
    by_quire = defaultdict(list)
    for row in rows:
        by_quire[row["quire"]].append(row["difference"])
    values = {q: statistics.mean(v) for q, v in sorted(by_quire.items())}
    pool = list(values.values())
    rng = random.Random(1947)
    boot = sorted(statistics.mean(rng.choices(pool, k=len(pool))) for _ in range(4000))
    return {
        "lines": len(rows), "folios": len(set(row["folio"] for row in rows)), "quires": len(pool),
        "certain_larger": sum(row["difference"] > 0 for row in rows),
        "equal": sum(row["difference"] == 0 for row in rows),
        "pooled_mean": statistics.mean(row["difference"] for row in rows),
        "equal_quire_mean": statistics.mean(pool), "quire_effects": values,
        "bootstrap_quire_95": [boot[int(.025 * len(boot))], boot[math.ceil(.975 * len(boot)) - 1]],
    }


def main():
    zl = ROOT.parent / "voynich-swarm" / "data" / "raw" / "ZL3b-n.txt"
    observed = json.loads(PRIOR.read_text())["s47_reanalysis"]
    rows, excluded, examined = reconstruct(ROOT / "predecessor/s47/positions.tsv", *read_zl(zl))
    old = {r["locus"]: r for r in observed["rows"]}
    rebuilt = {r["locus"]: r for r in rows}
    common = sorted(old.keys() & rebuilt.keys())
    fields = ("folio", "quire", "pair", "glyph_distance", "certain_left", "certain_px",
              "uncertain_px", "threshold", "difference", "counts_equal")
    mismatched = {key: {field: [old[key][field], rebuilt[key][field]]
                        for field in fields if old[key][field] != rebuilt[key][field]}
                  for key in common if any(old[key][field] != rebuilt[key][field] for field in fields)}
    control = {
        "examined_lines": examined, "reconstructed_lines": len(rows),
        "archive_completed_lines": len(old), "shared_loci": len(common),
        "old_only": sorted(old.keys() - rebuilt.keys()),
        "rebuilt_only": sorted(rebuilt.keys() - old.keys()),
        "mismatched_fields": mismatched, "exclusions": excluded,
        "original_rows_report": summary(list(old.values())),
        "original_rows_minus_original_alignment_fault": summary(
            [r for r in old.values() if r["locus"] != "f35r.8"]
        ),
    }
    (ROOT / "archive-recount.json").write_text(json.dumps(control, indent=2) + "\n")
    print(json.dumps(control, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.compare_blind_edges.py:
"""Unmask the agreed optical readings and trace the source detector intervals."""
import hashlib
import json
from pathlib import Path
import re
from statistics import mean


ROOT = Path(__file__).resolve().parent
Q = {
    "T24": ("f35r.8", 6, "f35r", "The 242-pixel group gap lies on the preceding detected row."),
    "T67": ("f115v.28", 27, "f115v", "The first detected group at x388–498 contains the red-centered star. The 76-pixel interval reaches from its envelope to the first text group."),
    "T39W": ("f56v.9", 8, "f56v", "Twelve detected groups are aligned to five words. The interval x1386–1428 reported for the comma falls at the measured period transition."),
    "T15": ("f58r.41", 41, "f58r", "The reported 40-pixel interval x1130–1170 lies earlier in the row. The actual comma transition lies inside the last combined detector group."),
}


def load(relative):
    return json.loads((ROOT / relative).read_text())


def gap(x_edges):
    return max(0, x_edges[1] - x_edges[0] - 1)


def bounds(ranges):
    left, right = ranges
    return gap((left[1], right[0])), gap((left[0], right[1]))


def extract_transcripts(locus):
    result = {}
    raw = ROOT.parent / "voynich-swarm" / "data" / "raw"
    for edition in ("ZL3b-n", "IT2a-n", "RF1b-e"):
        with (raw / (edition + ".txt")).open(encoding="utf-8-sig") as fh:
            entries = [line.partition(">")[2].strip()
                       for line in fh if line.startswith(f"<{locus},")]
        assert len(entries) == 1, (edition, locus)
        result[edition] = entries[0].removeprefix("<%>").removesuffix("<$>")
    return result


def marker_classes(text):
    classes = {}
    continuous = 0
    for char in text:
        if char in ".,":
            classes[continuous] = "period" if char == "." else "comma"
        else:
            continuous += 1
    return classes


def summarize(panel, locus, index, page, explanation, reads, old):
    masked = load(f"blind-read/{panel}.json")
    transcripts = extract_transcripts(locus)
    assert re.sub("[.,]", "", transcripts["ZL3b-n"]) == masked["separator_erased_eva"]
    by_pos = marker_classes(transcripts["ZL3b-n"])
    classes = {name: by_pos[pos] for name, pos in masked["transition_after_eva_chars"].items()}
    assert set(classes.values()) == {"period", "comma"}
    reverse = {kind: name for name, kind in classes.items()}
    a, b = reads.values()
    interreader = {
        name: [abs(i - j) for i, j in zip(a["edges"][name], b["edges"][name], strict=True)]
        for name in classes
    }
    assert max(all_values := [v for parts in interreader.values() for v in parts]) <= 10
    tape = {}
    for name, reader in reads.items():
        dot, comma = (reverse[k] for k in ("period", "comma"))
        point_d, point_c = (gap(reader["edges"][k]) for k in (dot, comma))
        lo_d, hi_d = bounds(reader["edge_ranges"][dot])
        lo_c, hi_c = bounds(reader["edge_ranges"][comma])
        tape[name] = {
            "period_gap_native_px": point_d, "comma_gap_native_px": point_c,
            "period_minus_comma_native_px": point_d - point_c,
            "conservative_range_from_edge_estimates": [lo_d - hi_c, hi_d - lo_c],
        }
    path = f"predecessor/s45/{page}.json"
    detector = load(path)
    assigned = next(row for row in detector["alignment"] if index in row["det"])
    groups = detector["lines"][index]["tokens"]
    measured_gap_origins = {
        key: [[left["x1"], right["x0"]] for left, right in zip(groups[:-1], groups[1:])
              if right["x0"] - left["x1"] == old[key]]
        for key in ("certain_px", "uncertain_px")
    }
    outcome = {
        "locus": locus, "panel": panel, "transliterations": transcripts, "ZL_marker_classes": classes,
        "prior_S47_row": old, "reported_S45_alignment": assigned,
        "native_detection_bbox": detector["lines"][index]["bbox"],
        "selected_detector_index_0_based": index,
        "S45_source_digest": hashlib.sha256((ROOT / path).read_bytes()).hexdigest(),
        "detector_x_group_intervals": [[row["x0"], row["x1"]] for row in groups],
        "detector_intervals_with_same_recorded_width": measured_gap_origins,
        "detector_link_diagnosis": explanation,
        "edges": {name: {key: mean([a["edges"][marker][i], b["edges"][marker][i]])
                         for i, key in enumerate(("left_glyph_right_edge", "right_glyph_left_edge"))}
                  for name, marker in reverse.items()},
        "interreader_edge_differences": interreader,
        "maximum_interreader_edge_difference": max(all_values),
        "both_20px_and_10px_edge_agreement": all(v <= 10 for v in all_values),
        "per_reader_gaps_native_px": tape,
        "mean_gap_native_px": {
            name: mean(row[f"{name}_gap_native_px"] for row in tape.values())
            for name in ("period", "comma")
        },
        "mean_difference_native_px": mean(row["period_minus_comma_native_px"] for row in tape.values()),
        "worst_case_sign_range_native_px": [
            min(row["conservative_range_from_edge_estimates"][0] for row in tape.values()),
            max(row["conservative_range_from_edge_estimates"][1] for row in tape.values()),
        ],
    }
    return outcome


def main():
    rows = load("blind-reads.json")["panels"]
    archived = {r["locus"]: r for r in load("predecessor/gap-audit-spec.json")["s47_reanalysis"]["rows"]}
    results = {
        panel: summarize(panel, locus, det, page, note, rows[panel], archived[locus])
        for panel, (locus, det, page, note) in Q.items()
    }
    assert all(result["mean_difference_native_px"] > 0 for result in results.values())
    assert all(result["prior_S47_row"]["difference"] < 0 for result in results.values())
    (ROOT / "native-edge-results.json").write_text(json.dumps(results, indent=2) + "\n")
    for result in results.values():
        print(result["locus"], result["mean_gap_native_px"], result["mean_difference_native_px"],
              result["worst_case_sign_range_native_px"], result["detector_intervals_with_same_recorded_width"])


if __name__ == "__main__":
    main()
